   973      if ((filters[i] != BLOSC_NOFILTER) && (filters[i] != BLOSC_TRUNC_PREC)) {
   974        _src = _dest;
   975        _dest = _tmp;
   976        _tmp = _src;
   977      }
   978    }
   979
   980    return errcode;
