  1392       not larger than blocksize */
  1393    if (context->nthreads == 1 || (context->sourcesize / context->blocksize) <= 1) {
  1394      /* The context for this 'thread' has no been initialized yet */
  1395      if (context->serial_context == NULL) {
  1396        context->serial_context = create_thread_context(context, 0);
  1397      }
  1398      else if (context->blocksize != context->serial_context->tmp_blocksize) {
  1399        free_thread_context(context->serial_context);
  1400        context->serial_context = create_thread_context(context, 0);
  1401      }
  1402      ntbytes = serial_blosc(context->serial_context);
  1403    }
  1404    else {
  1405      ntbytes = parallel_blosc(context);
  1406    }
  1407
  1408    return ntbytes;
